#!/usr/bin/env python3
# 產生 renderer/src/behavior/names_cpp_rust_go.json：C++ 標準函式庫（STL）、Rust、Go 的「呼叫名稱 → 行為分類」名稱表與 API 語意。
# 用法：python scripts/gen-name-tables.py（改了這裡就重跑，再 node scripts/embed-code-ui.js）。
# 名稱的寫法（要跟引擎的呼叫名稱候選一致，見 engine_1_core.js 的 rustCallCandidates／goCallCandidates）：
#   C++  ：呼叫名稱的最後一段（std::sort → sort、v.push_back() → push_back），跟 C 的名稱表合併使用（只對 .cc/.cpp/.cxx/.hpp 檔）。
#   Rust ：路徑呼叫 fs::read_to_string／File::open（完整路徑 std::fs::read_to_string 也會比對到最後兩段）、方法呼叫 .lock、巨集 println!。
#   Go   ：套件函式 os.Open（呼叫端的前綴）、方法 .Lock（任何接收者）、內建 make／append。
# 這些名稱是依官方文件知識整理，沒有逐條對照官方文件；有錯用 behavior_define 修正。
import json, os

def L(s):
    return [x for x in s.split() if x]

C = {}   # category -> {lang: [names]}
def add(cat, lang, names):
    C.setdefault(cat, {}).setdefault(lang, [])
    for n in L(names):
        if n not in C[cat][lang]:
            C[cat][lang].append(n)

