# ======================= API 語意（呼叫的引數與回傳值意義） =======================
def api(summary, params=None, ret=None, rules=None):
    d = {'summary': summary}
    d['parameters'] = [{'name': n, 'meaning': m} for n, m in (params or [])]
    if ret or rules:
        d['return'] = {'meaning': ret or ''}
        if rules:
            d['return']['rules'] = [{'when': {'op': o, 'value': v}, 'meaning': m} for o, v, m in rules]
    return d

API = {'cpp': {}, 'rust': {}, 'go': {}}
A = API['cpp']
A['make_shared'] = api('Allocates an object on the heap and returns a std::shared_ptr that owns it (one allocation for the object and its control block).', [('args', 'constructor arguments forwarded to the object type given in the template argument')], 'a shared_ptr (reference-counted owner); throws std::bad_alloc if allocation fails')
A['make_unique'] = api('Allocates an object on the heap and returns a std::unique_ptr that is its sole owner.', [('args', 'constructor arguments forwarded to the object type given in the template argument')], 'a unique_ptr (exclusive owner, freed automatically); throws std::bad_alloc if allocation fails')
A['getline'] = api('Reads one line from an input stream (up to the delimiter) into a string.', [('stream', 'the input stream (std::cin, an ifstream, ...)'), ('str', 'string that receives the line, without the delimiter'), ('delim', 'optional delimiter character (default newline)')], 'the stream itself; converts to false when nothing could be read (end of input or error)')
A['stoi'] = api('Converts a string to int (std::stoi).', [('str', 'text to parse'), ('pos', 'optional: receives the index of the first unparsed character'), ('base', 'numeric base (default 10)')], 'the parsed int; throws std::invalid_argument if no digits, std::out_of_range if the value does not fit')
A['stol'] = api('Converts a string to long (std::stol).', [('str', 'text to parse'), ('pos', 'optional: receives the index of the first unparsed character'), ('base', 'numeric base (default 10)')], 'the parsed long; throws std::invalid_argument / std::out_of_range')
A['stod'] = api('Converts a string to double (std::stod).', [('str', 'text to parse'), ('pos', 'optional: receives the index of the first unparsed character')], 'the parsed double; throws std::invalid_argument / std::out_of_range')
A['to_string'] = api('Converts a number to its decimal text (std::to_string).', [('value', 'integer or floating-point value')], 'a std::string')
