# 同一個名稱不能同時在兩個類別（引擎的查表是「後蓋前」，歸類會取決於類別順序）。自動處理：
#   - 以「.」開頭的方法名（任何接收者都會命中）出現在多個類別 → 太含糊，全部移除（寧可不分類也不要亂分類）
#   - 完整名稱（pkg.Func、a::b）重複 → 保留第一個登記的類別
dups = {}
for cat, langs in C.items():
    for l, ns in langs.items():
        for n in ns:
            dups.setdefault((l, n), []).append(cat)
removed_bare, removed_q = [], []
for (l, n), cs in dups.items():
    if len(cs) < 2:
        continue
    if n.startswith('.'):
        for c in cs:
            C[c][l].remove(n)
        removed_bare.append((l, n))
    else:
        for c in cs[1:]:
            C[c][l].remove(n)
        removed_q.append((l, n, cs[0]))
# 太泛用的方法名（任何型別都有同名方法）一律不分類：寧可留在「未分類」讓人看，也不要把 f.Close() 說成壓縮、把 path.join() 說成執行緒
DENY_BARE = {
    'go': set('.Close .Open .Create .Extract .Text .Bytes .Stat .Value .Stop .Store .Range .Cancel .Deadline .Name .Type .Index .Slice .Interface .Elem .Kind .Field .Method .IsNil .IsValid .Tag .Lookup .Convert .SetLen .SetCap .Entry .Select .Save .First .Where .Model .Table .Order .Limit .Offset .Raw .Count .Pluck .Transaction .Database .Collection .Conn .Stats .Rows .Columns .ColumnTypes .Begin .Pipeline .Distinct .Draw .Show .Resize .SetFocus .Layout .Clear .Scale .Translate .Rotate .Stroke .Sub .Before .After .Equal .Compare .Round .Unix .Year .Month .Day .Hour .Minute .Second .Date .Clock .Location .Zone .In .Local .Seconds .Minutes .Hours .Format .Parse .Grow .Cap .Info .Warn .Error .Debug .Fatal .Panic .Sugar .More .Token .ReadAll .Comma .Comment .Hostname .Port .Sum .Public .Generate .Start .Pid .ProcessState .Env .Dir .ExtraFiles .SysProcAttr .Input .High .Low .Toggle .SetSpeed .SetMode .Tx .Front .Back .Prev .Init .Move .Link .Unlink .Fix .Less .Put .Invoke .Acquire .Errors .Unsubscribe .Emit .On .Off .Once .Trigger .Notify .Listen .Poll .Dispatch .Bind .Connect .Serve .Fd'.split()),
    'rust': set('.bytes .flush .seek .metadata .parent .display .connect .get .post .put .delete .header .json .send_async .get_mut .into_inner .read .write .iter .store .swap .acquire .await .enter .abort .checked_add .checked_sub .format .trim .trim_start .trim_end .split .lines .chars .contains .starts_with .ends_with .replace .replacen .find .rfind .repeat .concat .push_str .as_str .into_bytes .eq_ignore_ascii_case .is_alphabetic .is_numeric .is_whitespace .to_string .to_owned .to_uppercase .to_lowercase .rsplit .init .ok_or .ok_or_else .map_err .and_then .or_else .context .with_context .unwrap_or .unwrap_or_else .unwrap_or_default .is .gen .sample .shuffle .choose .update .arg .args .envs .env .stdin .stdout .stderr .kill .id .status .execute .query .transaction .commit .rollback .fetch .first .prepare .entries .extract .toggle .is_high .is_low .to_array .submit .launch .run .save .resize .present .run_app .add_listener .set_handler .subscribe .listen .emit .on'.split()),
}
for l, deny in DENY_BARE.items():
    for cat in C:
        if l in C[cat]:
            C[cat][l] = [n for n in C[cat][l] if n not in deny]
print('移除含糊的方法名 %d 個（出現在多個類別）；完整名稱重複 %d 個（保留第一個類別）' % (len(removed_bare), len(removed_q)))

